'use strict';
const NoteEffects=(()=>{const clips={};for(const name of ['crumple','success','miss']){clips[name]=new Audio('assets/'+name+'.mp3');clips[name].preload='auto';clips[name].volume=name==='crumple'?.4:.32;}let zoom=1,panX=0,panY=0,pan=null,chain=Promise.resolve();
 function sound(name){if(store.settings.muted)return;const a=clips[name].cloneNode();a.volume=clips[name].volume;a.play().catch(()=>{});}
 function setZoom(value,origin){const r=$('#room').getBoundingClientRect(),before=zoom;zoom=M.clamp(value,1,2.5);if(origin){const ox=origin.x-r.left-r.width/2,oy=origin.y-r.top-r.height/2;panX=ox-(ox-panX)*zoom/before;panY=oy-(oy-panY)*zoom/before;}if(zoom===1){panX=0;panY=0;}panX=M.clamp(panX,-r.width*(zoom-1)/2,r.width*(zoom-1)/2);panY=M.clamp(panY,-r.height*(zoom-1)/2,r.height*(zoom-1)/2);$('#scene').style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`;$('#zoom-reset').textContent=Math.round(zoom*100)+'%';}
 function init(){const tools=$('#tools');tools.insertAdjacentHTML('afterbegin','<button id="zoom-out" title="Zoom out" aria-label="Zoom out">−</button><button id="zoom-reset" title="Fit room" aria-label="Fit room">100%</button><button id="zoom-in" title="Zoom in" aria-label="Zoom in">+</button><button id="paper-size" title="Paper size and layout" aria-label="Paper size and layout">▱</button><button id="sound-toggle" title="Turn sound off" aria-label="Turn sound off">♪</button>');$('#paper-size').onclick=paperSettings;$('#zoom-in').onclick=()=>setZoom(zoom+.25);$('#zoom-out').onclick=()=>setZoom(zoom-.25);$('#zoom-reset').onclick=()=>setZoom(1);const updateSound=()=>{$('#sound-toggle').textContent=store.settings.muted?'♩̸':'♪';$('#sound-toggle').title=store.settings.muted?'Turn sound on':'Turn sound off';$('#sound-toggle').setAttribute('aria-label',$('#sound-toggle').title);};updateSound();$('#sound-toggle').onclick=()=>{store.settings.muted=!store.settings.muted;updateSound();changed(false);};$('#room').addEventListener('wheel',e=>{if(e.target.closest('textarea')&&!e.ctrlKey)return;if(e.target.closest('input')&&!e.ctrlKey)return;e.preventDefault();setZoom(zoom+(e.deltaY<0?.15:-.15),{x:e.clientX,y:e.clientY});},{passive:false});$('#scene').addEventListener('pointerdown',e=>{if(zoom<=1||e.target.closest('.note')||e.button!==0)return;pan={x:e.clientX,y:e.clientY,px:panX,py:panY};$('#scene').setPointerCapture(e.pointerId);$('#scene').classList.add('panning');});window.addEventListener('pointermove',e=>{if(!pan)return;panX=pan.px+e.clientX-pan.x;panY=pan.py+e.clientY-pan.y;setZoom(zoom);});window.addEventListener('pointerup',()=>{pan=null;$('#scene').classList.remove('panning');});window.addEventListener('resize',()=>setZoom(zoom));}
 function paperSettings(){modal('<p class="eyebrow">Make a little room</p><h1>Small notes. A bigger picture.</h1><p>Make the papers smaller to keep more work in view. Zoom in whenever you want to read closely. Your text and positions are kept.</p><label for="paper-scale">Paper size: <b id="paper-scale-value">'+Math.round((store.settings.paperScale||1)*100)+'%</b></label><input id="paper-scale" type="range" min="55" max="110" step="5" value="'+Math.round((store.settings.paperScale||1)*100)+'" style="width:100%;margin:25px 0"><div class="actions"><button class="primary" id="paper-size-done">Back to my board</button><button class="secondary" id="arrange-papers">Arrange notes on board</button></div><p class="small muted">Arrange moves open notes into a grid. You can undo it immediately.</p>');$('#paper-scale').oninput=e=>{store.settings.paperScale=Number(e.target.value)/100;$('#paper-scale-value').textContent=e.target.value+'%';layout();changed(false);};$('#paper-size-done').onclick=()=>$('#modal').close();$('#arrange-papers').onclick=()=>{const notes=M.visible(store.notes),before=notes.map(n=>({id:n.id,x:n.x,y:n.y})),b=$('#board'),d=dims();const cols=Math.max(1,Math.floor(b.clientWidth/(d.w+12))),rows=Math.max(1,Math.ceil(notes.length/cols));notes.forEach((n,i)=>{n.x=cols===1?.5:(i%cols)/(cols-1);n.y=rows===1?.35:Math.floor(i/cols)/(rows-1);});layout();changed(false);$('#modal').close();toast('Notes arranged. Your words are unchanged.',()=>{for(const p of before){const n=store.notes.find(n=>n.id===p.id);if(n){n.x=p.x;n.y=p.y;}}layout();changed(false);});};}
 function snapshot(el){if(!el)return null;const rect=el.getBoundingClientRect(),copy=el.cloneNode(true);copy.classList.add('effect-paper');copy.querySelectorAll('button').forEach(b=>b.remove());copy.style.cssText=el.style.cssText;Object.assign(copy.style,{position:'fixed',left:rect.left+'px',top:rect.top+'px',width:rect.width+'px',height:rect.height+'px',margin:'0',transform:'none',zIndex:'100010',pointerEvents:'none'});copy.style.setProperty('--note-w',rect.width+'px');copy.style.setProperty('--note-h',rect.height+'px');copy.querySelectorAll('input,textarea').forEach((x,j)=>{x.value=el.querySelectorAll('input,textarea')[j].value;x.disabled=true;});return {copy,rect};}
 async function toss(note,shot){if(!shot)return;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const count=store.settings.tossCount=(store.settings.tossCount||0)+1,hit=count%6!==0;if(window.__NOTENEST_TEST__)(window.__tossResults??=[]).push({count,hit,paper:note.paper,asset:'ball-'+note.paper+'.png'});changed(false);if(reduced){sound(hit?'success':'miss');return;}
 const {copy,rect}=shot;document.body.append(copy);sound('crumple');const cx=rect.left+rect.width/2,cy=rect.top+rect.height/2;const crumple=copy.animate([{transform:'rotate(0deg) scale(1)',clipPath:'polygon(0 0,100% 0,100% 100%,0 100%)',filter:'contrast(1)'},{transform:'rotate(-12deg) skew(8deg,3deg) scale(.88,.76)',clipPath:'polygon(9% 0,88% 8%,100% 78%,72% 100%,7% 87%,0 28%)',filter:'contrast(1.15)',offset:.32},{transform:'rotate(26deg) skew(-12deg,-6deg) scale(.60,.47)',clipPath:'polygon(23% 0,86% 17%,100% 66%,69% 100%,16% 91%,0 36%)',filter:'contrast(1.35)',offset:.7},{transform:'rotate(66deg) scale(.25)',opacity:0,clipPath:'polygon(32% 0,85% 22%,100% 60%,67% 100%,20% 86%,0 35%)'}],{duration:720,easing:'ease-in-out',fill:'forwards'});
 const ball=document.createElement('img');ball.className='paper-ball';ball.src='assets/ball-'+note.paper+'.png';ball.alt='';ball.style.left=cx-38+'px';ball.style.top=cy-38+'px';ball.style.opacity='0';document.body.append(ball);setTimeout(()=>ball.animate([{opacity:0,transform:'scale(1.4)'},{opacity:1,transform:'scale(1)'}],{duration:220,fill:'forwards'}),520);await crumple.finished.catch(()=>{});copy.remove();
 const room=$('#room').getBoundingClientRect(),bx=room.right-Math.max(65,room.width*.065)-55,by=room.bottom-145;const basket=document.createElement('div');basket.className='toss-basket';basket.style.left=bx+'px';basket.style.top=by+'px';basket.innerHTML='<svg viewBox="0 0 110 130" aria-hidden="true"><defs><linearGradient id="metal"><stop stop-color="#646c66"/><stop offset=".5" stop-color="#bac1b6"/><stop offset="1" stop-color="#555e58"/></linearGradient><pattern id="mesh" width="11" height="12" patternUnits="userSpaceOnUse"><path d="M0 0L11 12M11 0L0 12" fill="none" stroke="#454b45" stroke-width="1.1"/></pattern></defs><ellipse cx="55" cy="20" rx="48" ry="13" fill="#232b23"/><path d="M8 20L22 118Q55 133 88 118L102 20Q55 41 8 20" fill="url(#metal)"/><path d="M8 20L22 118Q55 133 88 118L102 20Q55 41 8 20" fill="url(#mesh)" opacity=".5"/><ellipse cx="55" cy="20" rx="48" ry="13" fill="none" stroke="#d9dfcf" stroke-width="4"/></svg>';document.body.append(basket);basket.animate([{transform:'translateY(95px) scale(.55)',opacity:0},{transform:'translateY(-8px) scale(1.07)',opacity:1},{transform:'translateY(0) scale(1)',opacity:1}],{duration:350,fill:'forwards'});
 const targetX=bx+55,targetY=by+17,dx=targetX-cx,dy=targetY-cy,apex=Math.min(cy,by)-Math.max(110,room.height*.18),missOffset=hit?0:92;const trajectory=ball.animate([{transform:'translate(0,0) rotate(0deg) scale(1)'},{transform:`translate(${dx*.42}px,${apex-cy}px) rotate(200deg) scale(.85)`,offset:.43},{transform:`translate(${dx*.82+missOffset*.7}px,${dy*.55-35}px) rotate(360deg) scale(.62)`,offset:.76},{transform:`translate(${dx+missOffset}px,${dy+(hit?15:90)}px) rotate(510deg) scale(${hit?.35:.52})`,opacity:hit?0:1}],{duration:1000,easing:'cubic-bezier(.33,.05,.7,1)',fill:'forwards'});await trajectory.finished.catch(()=>{});sound(hit?'success':'miss');if(hit){basket.animate([{transform:'rotate(0)'},{transform:'rotate(-5deg)'},{transform:'rotate(4deg)'},{transform:'rotate(0)'}],{duration:350});ball.remove();}else{ball.animate([{transform:`translate(${dx+missOffset}px,${dy+90}px) rotate(510deg) scale(.52)`,opacity:1},{transform:`translate(${dx+missOffset+17}px,${dy+48}px) rotate(580deg) scale(.5)`,opacity:1,offset:.45},{transform:`translate(${dx+missOffset+44}px,${dy+106}px) rotate(650deg) scale(.48)`,opacity:0}],{duration:850,fill:'forwards'});setTimeout(()=>ball.remove(),900);}setTimeout(()=>{basket.animate([{transform:'translateY(0)',opacity:1},{transform:'translateY(85px)',opacity:0}],{duration:300,fill:'forwards'}).finished.then(()=>basket.remove()).catch(()=>basket.remove());},1100);}
 function complete(note,shot){chain=chain.catch(()=>{}).then(()=>toss(note,shot));return chain;}
 return {init,snapshot,complete,setZoom,whenIdle:()=>chain};})();
